# region: emit
def emit(raw):
    out = []
    for tok in raw[1:]:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
    return out

# region: gather
def gather(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: sift
def sift(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: fold
def fold(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return fold(sift(gather(emit(raw))))

